import os
from typing import Optional

import boto3
from botocore.exceptions import BotoCoreError, ClientError


def extract_text_from_image(image_path: str, region_name: Optional[str] = None) -> str:
    """
    Extract plain text from a scanned document image using Amazon Textract.

    Args:
        image_path: Path to a local image file (JPEG/PNG/TIFF/PDF not supported by detect_document_text).
        region_name: Optional AWS region for the Textract client.

    Returns:
        Extracted plain text as a single string.
    """
    with open(image_path, "rb") as f:
        document_bytes = f.read()

    client_kwargs = {}
    if region_name:
        client_kwargs["region_name"] = region_name

    textract = boto3.client("textract", **client_kwargs)

    try:
        response = textract.detect_document_text(Document={"Bytes": document_bytes})
    except (BotoCoreError, ClientError) as exc:
        raise RuntimeError(f"Textract OCR failed: {exc}") from exc

    lines = []
    for block in response.get("Blocks", []):
        if block.get("BlockType") == "LINE" and "Text" in block:
            lines.append(block["Text"])

    return "\n".join(lines)


def extract_layout_blocks(image_path: str, region_name: Optional[str] = None) -> list[dict]:
    """
    Extract layout-aware text block information from a scanned document image using Amazon Textract.

    Returns a list of dictionaries containing block metadata and text for LINE blocks.
    """
    with open(image_path, "rb") as f:
        document_bytes = f.read()

    client_kwargs = {}
    if region_name:
        client_kwargs["region_name"] = region_name

    textract = boto3.client("textract", **client_kwargs)

    try:
        response = textract.analyze_document(
            Document={"Bytes": document_bytes},
            FeatureTypes=["LAYOUT"],
        )
    except (BotoCoreError, ClientError):
        response = textract.detect_document_text(Document={"Bytes": document_bytes})

    results = []
    for block in response.get("Blocks", []):
        block_type = block.get("BlockType")
        if block_type in {"LINE", "LAYOUT_TEXT", "LAYOUT_TITLE", "LAYOUT_HEADER", "LAYOUT_FOOTER", "LAYOUT_SECTION_HEADER", "LAYOUT_LIST", "LAYOUT_TABLE", "LAYOUT_FIGURE"}:
            results.append(
                {
                    "block_type": block_type,
                    "text": block.get("Text", ""),
                    "confidence": block.get("Confidence"),
                    "geometry": block.get("Geometry", {}),
                    "id": block.get("Id"),
                    "relationships": block.get("Relationships", []),
                }
            )
    return results


if __name__ == "__main__":
    import sys

    if len(sys.argv) < 2:
        raise SystemExit("Usage: python ocr.py <image_path> [region_name]")

    img_path = sys.argv[1]
    region = sys.argv[2] if len(sys.argv) > 2 else os.getenv("AWS_REGION") or os.getenv("AWS_DEFAULT_REGION")

    text = extract_text_from_image(img_path, region)
    print(text)
